import React, { useState, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import './ManhwaViewer.css';

const IMAGES = [
  '/assets/manhwa/KakaoTalk_20260529_150306300.png',
  '/assets/manhwa/KakaoTalk_20260529_150316866.png',
  '/assets/manhwa/KakaoTalk_20260529_150335505.png',
  '/assets/manhwa/KakaoTalk_20260529_150405214.png',
];

export default function ManhwaViewer() {
  const navigate = useNavigate();
  const [index, setIndex] = useState(0);

  const goTo = useCallback((next) => {
    if (next < 0 || next >= IMAGES.length) return;
    setIndex(next);
  }, []);

  const handleImageClick = (e) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const clickX = e.clientX - rect.left;
    if (clickX < rect.width / 2) {
      goTo(index - 1);
    } else {
      goTo(index + 1);
    }
  };

  return (
    <div className="mw-root">
      {/* 뒤로가기 */}
      <button className="mw-back-btn" onClick={() => navigate(-1)}>← 나가기</button>

      {/* 뷰어 */}
      <div className="mw-container">
        <img
          className="mw-image"
          src={IMAGES[index]}
          alt={`만화 ${index + 1}페이지`}
          onClick={handleImageClick}
          draggable={false}
        />
      </div>

      {/* 하단 네비 */}
      <div className="mw-nav">
        <button
          className="mw-nav-btn"
          onClick={() => goTo(index - 1)}
          disabled={index === 0}
        >
          ◀ 이전
        </button>
        <span className="mw-page-text">{index + 1} / {IMAGES.length}</span>
        <button
          className="mw-nav-btn"
          onClick={() => goTo(index + 1)}
          disabled={index === IMAGES.length - 1}
        >
          다음 ▶
        </button>
      </div>
    </div>
  );
}
